import{_ as l,W as d,s as o,u as g,ah as i,I as p,w as a,Z as s,A as n}from"./chunks/framework.Dx7wo2et.js";import"./chunks/theme.CjgFg8Ql.js";const L=JSON.parse('{"title":"如何在 RHEL 9 上分步安装 PgAdmin4 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 RHEL 9 上分步安装 PgAdmin4 | LCTT (202303) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"如何在 RHEL 9 上分步安装 PgAdmin4 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 RHEL 9 上分步安装 PgAdmin4 | LCTT (202303) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202303/20230301.0 ⭐️ How to Install PgAdmin4 on RHEL 9 Step by Step","title":"如何在 RHEL 9 上分步安装 PgAdmin4","tag":"202303"},"relativePath":"202303/20230301.0 ⭐️ How to Install PgAdmin4 on RHEL 9 Step by Step.md","filePath":"[post].md"}'),r={name:"202303/20230301.0 ⭐️ How to Install PgAdmin4 on RHEL 9 Step by Step.md"};function h(m,t,c,u,b,P){const e=d("Link");return g(),o("div",null,[t[18]||(t[18]=i('<h1 id="如何在-rhel-9-上分步安装-pgadmin4" tabindex="-1">如何在 RHEL 9 上分步安装 PgAdmin4 <a class="header-anchor" href="#如何在-rhel-9-上分步安装-pgadmin4" aria-label="Permalink to 如何在 RHEL 9 上分步安装 PgAdmin4">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202303/12/080937o03a11xsz99zawzm.jpg" alt=""></p><p>PgAdmin4 是一个自由开源的基于网络的 PostgreSQL 管理和开发平台。它可以与本地或远程的服务器上的 PostgreSQL 数据库服务器进行交互，并使用直观的交互式仪表板显示服务器的统计数据。</p><p>PgAdmin4 是对 PgAdmin3 的重写，提供了以下显著的功能：</p><ul><li>具有直观的实时监控仪表盘的响应式 Web UI。</li><li>改进的 Web 界面，具有很酷的新面板和图标。</li><li>带有语法高亮的 SQL 查询编辑器。</li><li>全面的文档。</li><li>帮助你入门的有用提示。</li></ul><p>在本指南中，我们将演示如何在 RHEL 9 上安装 PgAdmin4。</p><h3 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to 先决条件">​</a></h3>',7)),p("p",null,[t[1]||(t[1]=a("在开始之前，确保你有一台 RHEL 9 服务器实例并安装了 PostgreSQL 数据库。请查看如何在 RHEL 9 上 ")),s(e,{href:"https://www.linuxtechi.com/how-to-install-postgresql-on-rhel/"},{default:n(()=>t[0]||(t[0]=[a("安装 PostgreSQL 15")])),_:1}),t[2]||(t[2]=a(" 的指南。"))]),t[19]||(t[19]=i('<p>在安装了 PostgreSQL 服务器后，继续执行以下步骤。</p><h3 id="步骤-1-在-rhel-9-上添加-pgadmin4-仓库" tabindex="-1">步骤 1）在 RHEL 9 上添加 PgAdmin4 仓库 <a class="header-anchor" href="#步骤-1-在-rhel-9-上添加-pgadmin4-仓库" aria-label="Permalink to 步骤 1）在 RHEL 9 上添加 PgAdmin4 仓库">​</a></h3><p>第一步是在 RHEL 9 上添加 PgAdmin4 仓库。但首先要安装 EPEL 仓库，它提供了基本的软件包。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo dnf install https://dl.fedoraproject.org/pub/epel/epel-release-latest-9.noarch.rpm</span></span></code></pre></div><p>接下来，安装 PgAdmin4 仓库，如下所示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo dnf install -y https://ftp.postgresql.org/pub/pgadmin/pgadmin4/yum/pgadmin4-redhat-repo-2-1.noarch.rpm</span></span></code></pre></div><p>完成后，为 PgAdmin4 和 EPEL 仓库建立一个缓存，如下所示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo dnf makecache</span></span></code></pre></div><h3 id="步骤-2-在-rhel-9-上安装-pgadmin4" tabindex="-1">步骤 2）在 RHEL 9 上安装 PgAdmin4 <a class="header-anchor" href="#步骤-2-在-rhel-9-上安装-pgadmin4" aria-label="Permalink to 步骤 2）在 RHEL 9 上安装 PgAdmin4">​</a></h3><p>安装好 PgAdmin4 和 EPEL 仓库后，继续使用 DNF 包管理器安装 PgAdmin4，如下所示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo dnf install pgadmin4 -y</span></span></code></pre></div><p>这将安装许多软件包，包括 PgAdmin4、Apache HTTP web 服务器和 Python 软件包，仅举几例：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Install-pgadmin4-rhel9-dnf-command.png" alt=""></p><p>要确认 PgAdmin4 是否已经安装，请运行以下命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ rpm -qi pgadmin4</span></span></code></pre></div><p>这将打印出相当多的信息，包括已安装软件包的名称、版本、发行和架构。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Pgadmin4-RPM-Package-Information-RHEL9.png" alt=""></p><h3 id="步骤-3-在-rhel-9-上启动-启用-pgadmin4" tabindex="-1">步骤 3）在 RHEL 9 上启动/启用 PgAdmin4 <a class="header-anchor" href="#步骤-3-在-rhel-9-上启动-启用-pgadmin4" aria-label="Permalink to 步骤 3）在 RHEL 9 上启动/启用 PgAdmin4">​</a></h3><p>此时，PgAdmin4 已成功安装。然而，你需要更进一步，让它运行起来。要启动 PgAdmin4 服务，请运行以下命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo systemctl start httpd</span></span></code></pre></div><p>还要确保每次系统启动时都能启动该服务。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo systemctl enable httpd</span></span></code></pre></div><p>要确认 PgAdmin4 正在运行，请执行以下命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo systemctl status httpd</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Start-Enable-Http-Pgadmin-RHEL9.png" alt=""></p><h3 id="步骤-4-在-rhel-9-上初始化-pgadmin4" tabindex="-1">步骤 4）在 RHEL 9 上初始化 PgAdmin4 <a class="header-anchor" href="#步骤-4-在-rhel-9-上初始化-pgadmin4" aria-label="Permalink to 步骤 4）在 RHEL 9 上初始化 PgAdmin4">​</a></h3><p>PgAdmin4 软件包提供了一个可配置的脚本来设置 PgAdmin 网络服务。这允许你创建一个用户账户，用来验证和配置 SELinux 策略和 Apache Web 服务器。</p><p>因此，如下运行该脚本：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo /usr/pgadmin4/bin/setup-web.sh</span></span></code></pre></div><p>提供你将在登录页面上作为登录凭证使用的电子邮件和密码。</p><p>注意:有时，你可能会遇到如下 “semanage: command not found” 的错误。这表明缺少 <code>semanage</code> 包。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/semange-not-found-pgadmin4-rhel9.png" alt=""></p><p>Semanage 是 SELinux（安全增强型 Linux）策略管理工具的简称，是一个用于配置 SELinux 策略某些方面的工具，不需要对策略源进行修改或重新编译。</p><p>为了解决这个错误，你需要检查提供 <code>semanage</code> 的软件包。你可以通过运行以下命令来完成：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo dnf provides /usr/sbin/semanage</span></span></code></pre></div><p>从输出中，你可以看到 <code>semanage</code> 是由 <code>policycoreutils-python-utils-3.3-6.el9_0.noarch</code> 包提供的。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/DNF-Whatprovides-semanage-RHEL9.png" alt=""></p><p>要安装这个软件包，请运行以下命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo dnf install policycoreutils-python-utils -y</span></span></code></pre></div><p>再一次如下运行 Pgadmin4 安装脚本。 提供电子邮件地址和密码，在提示时输入 <code>y</code>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo /usr/pgadmin4/bin/setup-web.sh</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/pgadmin-setup-web-script-rhel9.png" alt=""></p><h3 id="步骤-5-访问-pgadmin4-的-web-界面" tabindex="-1">步骤 5）访问 PgAdmin4 的 Web 界面 <a class="header-anchor" href="#步骤-5-访问-pgadmin4-的-web-界面" aria-label="Permalink to 步骤 5）访问 PgAdmin4 的 Web 界面">​</a></h3><p>此时，PgAdmin4 已经成功安装。要从网络浏览器访问它，请前往以下地址：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://server-ip/pgadmin4</span></span></code></pre></div><p>你会看到登录网页界面。请确保提供你在运行安装脚本时提供的 Email 和密码，并点击 “<ruby>登录<rt>Login</rt></ruby>”：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Pgadmin4-Login-Page-RHEL9.png" alt=""></p><p>登录后，PgAdmin4 的仪表板将出现在视图中，如图所示：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Dashboard-Pgadmin4-RHEL9.png" alt=""></p><p>要添加一个可以由 PgAdmin4 管理的服务器，请点击 “<ruby>添加新服务器<rt>Add New Server</rt></ruby>”：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Add-New-PostgreSQL-to-Pgadmin4-RHEL9.png" alt=""></p><p>在 “<ruby>通用<rt>General</rt></ruby>” 选项卡中，填写服务器的名称，并添加注释，以便更好地描述：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/General-Description-Pgadmin-New-PostgreSQL.png" alt=""></p><p>接下来，点击 “<ruby>连接<rt>Connection</rt></ruby>”，填写主机名/地址、端口、维护数据库、用户名和密码。然后最后点击 “<ruby>保存<rt>Save</rt></ruby>”：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/Connection-Details-PostgreSQL-Pgadmin4-GUI.png" alt=""></p><p>此后，你会看到 PosrgreSQL 服务器的统计数据显示在互动和直观的仪表板上。在左边的侧边栏，你可以浏览各种 PostgreSQL 参数：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/03/PostgreSQL-Statistics-Dashboard-Pgadmin4.png" alt=""></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to 总结">​</a></h3><p>我们希望你觉得本指南内容丰富，请在下面的评论部分发表你的疑问和反馈。</p><hr>',60)),p("p",null,[t[4]||(t[4]=a("via: ")),s(e,{href:"https://www.linuxtechi.com/how-to-install-pgadmin-on-rhel/"},{default:n(()=>t[3]||(t[3]=[a("https://www.linuxtechi.com/how-to-install-pgadmin-on-rhel/")])),_:1})]),p("p",null,[t[9]||(t[9]=a("作者：")),s(e,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:n(()=>t[5]||(t[5]=[a("Pradeep Kumar")])),_:1}),t[10]||(t[10]=a(" 选题：")),s(e,{href:"https://github.com/lkxed/"},{default:n(()=>t[6]||(t[6]=[a("lkxed")])),_:1}),t[11]||(t[11]=a(" 译者：")),s(e,{href:"https://github.com/geekpi"},{default:n(()=>t[7]||(t[7]=[a("geekpi")])),_:1}),t[12]||(t[12]=a(" 校对：")),s(e,{href:"https://github.com/wxy"},{default:n(()=>t[8]||(t[8]=[a("wxy")])),_:1})]),p("p",null,[t[15]||(t[15]=a("本文由 ")),s(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>t[13]||(t[13]=[a("LCTT")])),_:1}),t[16]||(t[16]=a(" 原创编译，")),s(e,{href:"https://linux.cn/"},{default:n(()=>t[14]||(t[14]=[a("Linux中国")])),_:1}),t[17]||(t[17]=a(" 荣誉推出"))])])}const k=l(r,[["render",h]]);export{L as __pageData,k as default};
